        n = len(cnf[0])
        A = [[0] * (n + 1) for _ in range(n)]
        b = [0] * n
        for clause in cnf:
            for literal in clause:
                var = abs(literal) - 1
                if literal > 0:
                    A[var][var] += 1
                else:
                    A[n][var] -= 1
                    A[var][n] -= 1
                    b[var] += 1
        return A, b

    def gaussian_elimination(A, b):
        n = len(b)
        for i in range(n):
            max_row = i
            for j in range(i + 1, n):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            b[i], b[max_row] = b[max_row], b[i]
            for j in range(i + 1, n):
                factor = A[j][i] / A[i][i]
                for k in range(i, n + 1):
                    A[j][k] -= factor * A[i][k]
                b[j] -= factor * b[i]
        return A, b

    def matrix_rank(A):
        rank = 0
        for row in A:
